import React from 'react';
import { StyleSheet, TextInput } from 'react-native';
import { colors, fontFamily, fontSize, radii } from '../theme';
/** Shared native numeric-code field styling. It contains no authentication behavior. */
export function NumericCodeInput({ value, onChangeText, length = 4, placeholder = '6-digit code', phone = false }: { value: string; onChangeText: (value: string) => void; length?: number; placeholder?: string; phone?: boolean }) { return <TextInput value={value} onChangeText={(next) => onChangeText(phone ? next.replace(/[^+\d]/g, '').replace(/(?!^)\+/g, '').slice(0, length) : next.replace(/\D/g, '').slice(0, length))} keyboardType={phone ? 'phone-pad' : 'number-pad'} maxLength={length} placeholder={placeholder} placeholderTextColor={colors.textMuted} selectionColor={colors.primary} showSoftInputOnFocus style={[styles.input, phone && styles.phoneInput]} />; }
const styles = StyleSheet.create({ input: { backgroundColor: colors.bg, borderColor: colors.border, borderRadius: radii.md, borderWidth: 1, color: colors.textPrimary, fontFamily: 'System', fontSize: fontSize.xl, letterSpacing: 8, padding: 14, textAlign: 'center' }, phoneInput: { letterSpacing: 2, textAlign: 'left' } });
